// MIT. Source-selected ODR workspace engine; all record semantics are original core APIs.
import fs from 'node:fs/promises';
import {constants} from 'node:fs';
import path from 'node:path';
import {pathToFileURL,fileURLToPath} from 'node:url';
import {createHash,randomUUID} from 'node:crypto';
export const sha=b=>createHash('sha256').update(b).digest('hex');
const fail=(code,message,extra={})=>{throw Object.assign(new Error(message),{code,...extra});};
const need=(ok,code,message)=>ok||fail(code,message);
export async function readJSON(p){const h=await fs.open(p,constants.O_RDONLY|constants.O_NOFOLLOW);try{const st=await h.stat();need(st.isFile()&&st.size<=128*1024*1024,'ODR_FILE','Select a complete ordinary JSON file within 128 MiB.');const b=await h.readFile();return JSON.parse(new TextDecoder('utf-8',{fatal:true}).decode(b));}finally{await h.close();}}
export async function atomic(p,value){
 const body=typeof value==='string'?value:JSON.stringify(value,null,2)+'\n';
 const parent=path.dirname(p),temporary=path.join(parent,'.odr-'+randomUUID());
 const h=await fs.open(temporary,'wx',0o600);
 try{await h.writeFile(body);await h.sync();await h.close();await fs.rename(temporary,p);const d=await fs.open(parent,'r');try{await d.sync();}finally{await d.close();}}
 finally{await h.close().catch(()=>{});await fs.unlink(temporary).catch(e=>{if(e.code!=='ENOENT')throw e;});}
}
export async function loadEngine(source,application){
 const core=await import(pathToFileURL(path.join(source,'src/core.mjs')).href);
 const kernel=core.createWorkbench({hash:sha,uuid:randomUUID});
 need(application?.schema==='commons.odr-alpha-application.v1','ODR_SOURCE_SCHEMA','Select the complete original application source.');
 for(const [name,text]of Object.entries(application.files||{}))need(typeof text==='string'&&application.manifest[name]===sha(text),'ODR_SOURCE_CHANGED','Complete original application bytes differ.');
 need(Object.keys(application.files||{}).length===Object.keys(application.manifest||{}).length,'ODR_SOURCE_CHANGED','Complete original source membership differs.');
 const canonical=core.canonical,applicationDigest=sha(canonical(application));
 const selected=(a)=>a?.schema===application.schema&&canonical(a.files)===canonical(application.files)&&canonical(a.manifest)===canonical(application.manifest);
 function receive(envelope){const r=kernel.receiveHandover(envelope);return r;}
 function validate(envelope,{selectedSource=true}={}){const r=receive(envelope);if(selectedSource)need(selected(r.application),'ODR_SELECTED_SOURCE','The handover must retain this exact selected source edition.');return r;}
 function rebind(envelope){
  const r=receive(envelope);
  const next=selected(r.application)?r.application:{...application,received_application:r.application};
  return r.workspace.handover(next,r.working_drafts);
 }
 function preserve(before,after){
  validate(before);validate(after);
  const a=before.workspace,b=after.workspace;
  need(a.id===b.id&&a.operation===b.operation&&a.created_at===b.created_at,'ODR_WORKSPACE_CHANGED','Keep the original workspace identity, operation and creation.');
  need(b.revision>=a.revision&&b.history.length>=a.history.length&&b.events.length>=a.events.length,'ODR_HISTORY_REWIND','Keep complete original history before any onward changes.');
  need(canonical(b.history.slice(0,a.history.length))===canonical(a.history)&&canonical(b.events.slice(0,a.events.length))===canonical(a.events),'ODR_HISTORY_CHANGED','An original saved event or full record revision changed.');
  for(const [kind,rows]of Object.entries(a.records))for(const [id,row]of Object.entries(rows)){
   const next=b.records[kind]?.[id];
   need(next&&next.revision>=row.revision&&(next.revision!==row.revision||canonical(next.value)===canonical(row.value)),'ODR_HEAD_REWIND','An original current record is missing, rewound or changed without a revision.');
  }
  if(before.application.received_application){
   const original=canonical(before.application.received_application);let retained=false,node=after.application.received_application;
   while(node){if(canonical(node)===original){retained=true;break;}node=node.received_application;}
   need(retained,'ODR_SOURCE_LINEAGE_CHANGED','Preserve the original received application lineage.');
  }
  need(canonical(a.records.sources)===canonical(Object.fromEntries(Object.keys(a.records.sources).map(id=>[id,b.records.sources[id]]))),'ODR_SOURCE_RECORD_CHANGED','Retain each original immutable source edition.');
 }
 return {core,kernel,canonical,application,applicationDigest,selected,receive,validate,rebind,preserve};
}
export async function installedEngine(root){
 const installation=await readJSON(path.join(root,'installation.json'));
 need(installation.directory===root&&installation.schema==='stellar-forge.odr-installation.v1','ODR_INSTALLATION_CHANGED','The selected original installation moved or changed.');
 const edition=path.join(root,'editions',installation.source_identity),application=await readJSON(path.join(edition,'APPLICATION.json'));
 const engine=await loadEngine(path.join(edition,'source'),application);
 const currentPath=path.join(root,'workspace','CURRENT.json');
 const handover=await readJSON(currentPath);engine.validate(handover);
 need(handover.workspace.id===installation.workspace_id,'ODR_WORKSPACE_CHANGED','The selected original workspace identity changed.');
 return {root,installation,edition,application,engine,currentPath,handover};
}
export async function commitHandover(ctx,submitted,expectedDigest){
 ctx.engine.validate(submitted);
 need(typeof expectedDigest==='string'&&/^[a-f0-9]{64}$/.test(expectedDigest),'ODR_EXPECTED_DIGEST','Select the original complete handover digest.');
 const payloadDigest=submitted.payload_sha256,key=sha(expectedDigest+'\0'+payloadDigest);
 const journal=path.join(ctx.root,'workspace','commits',key);await fs.mkdir(journal,{recursive:true,mode:0o700});
 const request={expectedDigest,payloadDigest,installationId:ctx.installation.installation_id,sourceIdentity:ctx.installation.source_identity,handover:submitted};
 const requestPath=path.join(journal,'REQUEST.json'),commitPath=path.join(journal,'COMMIT.json'),resultPath=path.join(journal,'RESULT.json');
 let retained;try{retained=await readJSON(requestPath);}catch(e){if(e.code!=='ENOENT')throw e;await atomic(requestPath,request);retained=request;}
 need(ctx.engine.canonical(retained)===ctx.engine.canonical(request),'ODR_REQUEST_CHANGED','Keep the exact pending original save payload and expected digest.');
 let result;try{result=await readJSON(resultPath);}catch(e){if(e.code!=='ENOENT')throw e;}
 let current=await readJSON(ctx.currentPath);ctx.engine.validate(current);
 if(result){ctx.engine.preserve(submitted,current);return result;}
 let commit;try{commit=await readJSON(commitPath);}catch(e){if(e.code!=='ENOENT')throw e;}
 if(!commit){
  if(current.payload_sha256===payloadDigest){
   const all=await fs.readdir(path.dirname(journal),{withFileTypes:true});
   for(const entry of all){if(!entry.isDirectory()||entry.name===key)continue;let old;
    try{old=await readJSON(path.join(path.dirname(journal),entry.name,'COMMIT.json'));}catch(err){if(err.code==='ENOENT')continue;throw err;}
    const r=old.receipt;
    if(r?.payloadDigest===payloadDigest&&r.installationId===ctx.installation.installation_id&&r.sourceIdentity===ctx.installation.source_identity){
     need(ctx.engine.canonical(old.request.handover)===ctx.engine.canonical(submitted),'ODR_PAYLOAD_CHANGED','The committed payload identity differs from its original bytes.');
     await atomic(commitPath,{request,receipt:r});await atomic(resultPath,r);return r;
    }
   }
  }
  if(current.payload_sha256!==expectedDigest&&current.payload_sha256!==payloadDigest)
   fail('ODR_REVISION_CONFLICT','The installed workspace changed. Receive the complete current handover explicitly before reconciling this retained draft.',{currentDigest:current.payload_sha256,currentHandover:current});
  ctx.engine.preserve(current,submitted);
  result={schema:'commons.odr-installed-save.v1',installationId:ctx.installation.installation_id,workspaceId:submitted.workspace.id,sourceIdentity:ctx.installation.source_identity,payloadDigest,currentDigest:payloadDigest,revision:submitted.workspace.revision,committedAt:new Date().toISOString()};
  commit={request,receipt:result};await atomic(commitPath,commit);
 }else{
  need(ctx.engine.canonical(commit.request)===ctx.engine.canonical(request),'ODR_REQUEST_CHANGED','The retained commit belongs to another original save.');result=commit.receipt;
 }
 if(current.payload_sha256===expectedDigest){ctx.engine.preserve(current,submitted);await atomic(ctx.currentPath,submitted);}
 else if(current.payload_sha256!==payloadDigest){ctx.engine.preserve(submitted,current);}
 await atomic(resultPath,result);return result;
}
export async function execute(input){
 const {source,application,operation,args={}}=input;
 if(operation==='validate'){const e=await loadEngine(source,application),h=await readJSON(args.handover);e.validate(h);return{workspace_id:h.workspace.id,revision:h.workspace.revision,digest:h.payload_sha256};}
 if(operation==='initialize'){
  const e=await loadEngine(source,application);
  const envelope=args.handover?e.rebind(await readJSON(args.handover)):e.kernel.workspace().handover(application,null);
  e.validate(envelope);await atomic(args.output,envelope);
  return {workspace_id:envelope.workspace.id,revision:envelope.workspace.revision,digest:envelope.payload_sha256,application_sha256:e.applicationDigest};
 }
 if(operation==='rebind'){
  const e=await loadEngine(source,application),old=await readJSON(args.handover),envelope=e.rebind(old);
  e.validate(envelope);need(envelope.workspace.id===old.workspace.id&&e.canonical(envelope.workspace)===e.canonical(old.workspace),'ODR_REBIND_CHANGED','Source adoption must preserve the complete original workspace.');
  await atomic(args.output,envelope);return{workspace_id:envelope.workspace.id,revision:envelope.workspace.revision,digest:envelope.payload_sha256,application_sha256:e.applicationDigest};
 }
 const ctx=await installedEngine(args.directory),{engine:e,handover:h}=ctx;
 if(operation==='inspect')return{workspace_id:h.workspace.id,revision:h.workspace.revision,digest:h.payload_sha256,source_files:Object.keys(e.application.files).length,application_sha256:e.applicationDigest,records:Object.fromEntries(Object.entries(h.workspace.records).map(([k,v])=>[k,Object.keys(v).length])),history_rows:h.workspace.history.length};
 if(operation==='workspace.receive')return commitHandover(ctx,await readJSON(args.file),args.expected_digest);
 if(operation==='workspace.state')return h.workspace;
 if(operation==='workspace.handover')return h;
 const ws=e.receive(h).workspace;
 if(operation==='workspace.record')return ws.get(args.kind,args.id);
 if(operation==='workspace.history')return ws.history(args.kind,args.id);
 if(operation==='workspace.comparison')return ws.comparison(args.ids,args.baseline_id);
 if(operation==='workspace.export'){
  if(args.kind==='workspace')await atomic(args.output,JSON.stringify(h,null,2)+'\n');
  else if(args.kind==='report')await atomic(args.output,e.core.renderReport(h.workspace));
  else if(args.kind==='application')await atomic(args.output,JSON.stringify(h.application,null,2)+'\n');
  else fail('ODR_EXPORT_KIND','Select workspace, report or application.');
  const b=await fs.readFile(args.output);return{path:args.output,bytes:b.length,sha256:sha(b),workspace_id:h.workspace.id,digest:h.payload_sha256};
 }
 fail('ODR_OPERATION','Select an original workspace operation.');
}
if(process.argv[1]&&path.resolve(process.argv[1])===path.resolve(fileURLToPath(import.meta.url))){
 try{let body='';for await(const b of process.stdin){body+=b;need(Buffer.byteLength(body)<=128*1024*1024,'ODR_REQUEST_LIMIT','Receive the complete request within 128 MiB.');}const value=await execute(JSON.parse(body));process.stdout.write(JSON.stringify({ok:true,result:value})+'\n');}
 catch(e){process.stdout.write(JSON.stringify({ok:false,error:{code:e.code||'ODR_ENGINE_FAILED',message:e.message,currentDigest:e.currentDigest,currentHandover:e.currentHandover}})+'\n');process.exitCode=1;}
}

// MIT. Direct managed loopback host for the complete original offline ODR application.
import http from 'node:http';
import fs from 'node:fs/promises';
import path from 'node:path';
import {randomBytes,timingSafeEqual} from 'node:crypto';
import {installedEngine,readJSON,atomic,sha,commitHandover} from './engine.mjs';
const args={};for(let i=2;i<process.argv.length;i+=2){if(!process.argv[i]?.startsWith('--')||!process.argv[i+1])throw Error('Complete original service arguments required.');args[process.argv[i].slice(2)]=process.argv[i+1];}
const root=path.resolve(args.directory),ctx=await installedEngine(root),i=ctx.installation;
for(const [key,value]of [['installation-id',i.installation_id],['source-identity',i.source_identity],['workspace-id',i.workspace_id]])if(args[key]!==value)throw Error('Original service selection changed: '+key);
const port=Number(args.port||0);if(!Number.isInteger(port)||port<0||port>65535)throw Error('Select an available loopback port.');
const selectedRoot=await fs.lstat(root,{bigint:true});if(selectedRoot.dev.toString()!==args.device||selectedRoot.ino.toString()!==args.inode)throw Error('Original installation directory identity changed.');
const htmlPath=path.join(ctx.edition,'built','ODR_Alpha_Workbench.html'),html=await fs.readFile(htmlPath,'utf8');
const build=await readJSON(path.join(ctx.edition,'BUILD.json'));if(sha(html)!==build.html.sha256)throw Error('Original built application changed.');
const token=randomBytes(32).toString('hex'),cookie=randomBytes(32).toString('hex'),cookieName='odr_'+i.installation_id.replaceAll('-','')+'_'+randomBytes(8).toString('hex');
const equal=(a,b)=>typeof a==='string'&&a.length===b.length&&timingSafeEqual(Buffer.from(a),Buffer.from(b));
let origin,tail=Promise.resolve(),closing=false;const active=new Set();
const serial=fn=>{const p=tail.then(fn);tail=p.catch(()=>{});return p;};
function send(res,status,value,type='application/json',extra={}){
 if(res.destroyed||res.writableEnded)return;
 const text=typeof value==='string'?value:JSON.stringify(value);res.writeHead(status,{'Content-Type':type,'Content-Length':Buffer.byteLength(text),'Cache-Control':'no-store','X-Content-Type-Options':'nosniff','Connection':'close',...extra});res.end(text);
}
const scriptJSON=v=>JSON.stringify(v).replace(/</g,'\\u003c').replace(/\u2028/g,'\\u2028').replace(/\u2029/g,'\\u2029');
async function installedPage(){
 const current=await readJSON(ctx.currentPath);ctx.engine.validate(current);
 const descriptor={schema:'commons.odr-installed-host.v1',installationId:i.installation_id,sourceIdentity:i.source_identity,initialHandover:current,currentDigest:current.payload_sha256,selectedApplication:{schema:ctx.application.schema,sha256:ctx.engine.applicationDigest,manifest:ctx.application.manifest}};
 const script='<script>window.ODR_INSTALLED=Object.assign('+scriptJSON(descriptor)+',{save:async function(handover,expectedDigest){const r=await fetch("/api/save",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({handover:handover,expectedDigest:expectedDigest})});const v=await r.json();if(!r.ok){const e=new Error(v.message||"Installed save failed");Object.assign(e,v);throw e;}return v;}});</script>';
 if(!html.includes('<script id="application-source"'))throw Error('Original application has no selected source bootstrap seam.');
 return html.replace('<script id="application-source"',()=>script+'<script id="application-source"');
}
const server=http.createServer((req,res)=>{
 const task=(async()=>{
  if(req.headers.host!==new URL(origin).host)return send(res,421,{code:'ODR_HOST',message:'Select the original loopback host.'});
  const url=new URL(req.url,origin);
  if(url.pathname==='/'&&req.method==='GET'&&url.searchParams.has('key')){
   if(!equal(url.searchParams.get('key'),token))return send(res,403,{code:'ODR_SESSION',message:'Receive the selected original ready URL.'});
   return send(res,303,'','text/plain',{'Location':'/','Set-Cookie':cookieName+'='+cookie+'; HttpOnly; SameSite=Strict; Path=/'});
  }
  const selected=(req.headers.cookie||'').split(';').map(x=>x.trim()).find(x=>x.startsWith(cookieName+'='))?.slice(cookieName.length+1);
  if(!equal(selected,cookie))return send(res,403,{code:'ODR_SESSION',message:'Open the selected private application session.'});
  if(req.method==='GET'&&url.pathname==='/'&&!url.search)return send(res,200,await installedPage(),'text/html; charset=utf-8');
  if(req.method==='GET'&&url.pathname==='/api/current')return send(res,200,await readJSON(ctx.currentPath));
  if(req.method==='GET'&&url.pathname==='/healthz')return send(res,200,{schema:'commons.odr-installed-health.v1',installationId:i.installation_id,workspaceId:i.workspace_id,sourceIdentity:i.source_identity});
  if(req.method!=='POST'||url.pathname!=='/api/save')return send(res,404,{code:'ODR_ROUTE',message:'Use the original installed application.'});
  if(closing)return send(res,503,{code:'ODR_CLOSING',message:'The original service is draining saved work.'});
  if(req.headers.origin!==origin||!/^application\/json(?:;|$)/i.test(req.headers['content-type']||''))return send(res,403,{code:'ODR_ORIGIN',message:'Use the original same-origin application controls.'});
  const chunks=[];let size=0;
  for await(const block of req){size+=block.length;if(size>128*1024*1024)return send(res,413,{code:'ODR_SIZE',message:'The full handover exceeds the declared 128 MiB receiving limit.'});chunks.push(block);}
  const input=JSON.parse(new TextDecoder('utf-8',{fatal:true}).decode(Buffer.concat(chunks)));
  if(Object.keys(input).sort().join(',')!=='expectedDigest,handover')return send(res,400,{code:'ODR_FIELDS',message:'Retain the complete original save payload and expected digest.'});
  const receipt=await serial(()=>commitHandover(ctx,input.handover,input.expectedDigest));send(res,200,receipt);
 })().catch(e=>send(res,e.code==='ODR_REVISION_CONFLICT'?409:400,{code:e.code||'ODR_RECEIVING',message:e.message,...(e.currentDigest?{currentDigest:e.currentDigest,currentHandover:e.currentHandover}:{})}));
 active.add(task);task.finally(()=>active.delete(task));
});
await new Promise((resolve,reject)=>{server.once('error',reject);server.listen(port,'127.0.0.1',resolve);});
origin='http://127.0.0.1:'+server.address().port;
const identity={schema:'stellar-forge.odr-process.v1',pid:process.pid,role:'operator',directory:root,installation_id:i.installation_id,source_identity:i.source_identity,workspace_id:i.workspace_id,device:selectedRoot.dev.toString(),inode:selectedRoot.ino.toString(),ready_file:args['ready-file'],origin,entry_sha256:sha(await fs.readFile(new URL(import.meta.url))),engine_sha256:sha(await fs.readFile(new URL('./engine.mjs',import.meta.url))),application_sha256:ctx.engine.applicationDigest};
const ready={...identity,url:origin+'/?key='+token};const file=await fs.open(args['ready-file'],'wx',0o600);try{await file.writeFile(JSON.stringify(ready)+'\n');await file.sync();}finally{await file.close();}
const dir=await fs.open(path.dirname(args['ready-file']),'r');try{await dir.sync();}finally{await dir.close();}
process.stdout.write(JSON.stringify(identity)+'\n');
async function stop(){if(closing)return;closing=true;server.close();await Promise.allSettled([...active]);await tail;server.closeAllConnections?.();process.exitCode=0;}
process.on('SIGTERM',()=>{void stop();});process.on('SIGINT',()=>{void stop();});

"""Source-selected ODR installations; original core owns the whole workspace."""
from __future__ import annotations
from datetime import datetime,timezone
import os,sys,uuid
from pathlib import Path
from files import *
from source import *
INSTALL_SCHEMA="stellar-forge.odr-installation.v1"
SNAPSHOT_SCHEMA="stellar-forge.odr-installation-archive.v1"
SOURCE_ROOT=Path(__file__).resolve().parent
def now():return datetime.now(timezone.utc).isoformat()
def input_file(path):return {k:v for k,v in file_identity(path).items() if k in ("path","bytes","sha256")}
def python_selection(path):
    p=absolute(path).resolve(strict=True);v=file_identity(p);need(os.access(p,os.X_OK),"python_executable","Select an installed Python interpreter.")
    result=subprocess.run([str(p),"-c","import sys;print('.'.join(map(str,sys.version_info[:3])))"],capture_output=True,text=True,timeout=30)
    need(result.returncode==0 and tuple(map(int,result.stdout.strip().split(".")))>=(3,10),"python_version","Python 3.10 or later is required.")
    return {"path":str(p),"version":result.stdout.strip(),"sha256":v["sha256"],"bytes":v["bytes"]}
def installation(path,verify=True):
    root=directory(path,private=True);value=read_json(root/"installation.json")
    need(value.get("schema")==INSTALL_SCHEMA and value.get("directory")==str(root),"installation_changed","Select the complete original installation.")
    identifier(value["installation_id"]);need(value.get("workspace")==str(root/"workspace"),"workspace_changed","Keep the original inner workspace location.")
    if verify:read_edition(root,value["source_identity"]);verify_node(value["node"])
    return value
def summary(value):
    root=Path(value["directory"]);edition,app,_=read_edition(root,value["source_identity"]);info=root.stat()
    return {"installation_id":value["installation_id"],"operation_id":value["operation_id"],"source_identity":value["source_identity"],"workspace_id":value["workspace_id"],"python":value["python"],"node":value["node"],"paths":{"directory":str(root),"source":str(edition/"source"),"application":str(edition/"source"),"workspace":value["workspace"],"bridge":str(edition/"bridge"),"html":str(edition/"built"/"ODR_Alpha_Workbench.html")},"binding":{"directory":str(root),"device":str(info.st_dev),"inode":str(info.st_ino)},"received_from":value.get("received_from")}
def check_binding(value,binding):
    if binding is None:return
    exact(binding,("installation_id","source_identity"),("installation_id","source_identity"))
    need(all(value[k]==binding[k] for k in binding),"installation_changed","Inspect the original installation and source before operating it.")
def selected_engine(root,value,operation,args=None):
    return engine(Path(root),value["source_identity"],value["node"],operation,{"directory":str(root),**(args or {})})
def journal(root,op,kind,request):
    target=directory(root/"operations"/identifier(op),create=True,private=True)
    once(target/"REQUEST.json",encoded({"schema":"stellar-forge.odr-lifecycle-request.v1","operation_id":op,"kind":kind,"request":request}))
    return target
def finish(path,result):once(path/"RESULT.json",encoded(result));return result
def commit(root,path,result,handover=None):
    if handover is not None:
        if (path/"TARGET_HANDOVER.json").exists():need(read_json(path/"TARGET_HANDOVER.json",MAX_SOURCE_BYTES)==handover,"handover_changed","The retained transition handover differs.")
        else:once(path/"TARGET_HANDOVER.json",encoded(handover))
    once(path/"COMMIT.json",encoded(result))
    if handover is not None:save(root/"workspace"/"CURRENT.json",handover)
    save(root/"installation.json",result["installation"])
    return finish(path,result)
def replay(root,op,kind,selection):
    path=root/"operations"/identifier(op)
    if not (path/"REQUEST.json").exists():return None
    record=read_json(path/"REQUEST.json");request=record["request"]
    need(record["kind"]==kind and request["selection"]==selection,"operation_conflict","Keep the exact original operation and selected inputs.")
    result=read_json(path/"RESULT.json") if (path/"RESULT.json").exists() else None
    if result is None and (path/"COMMIT.json").exists():
        result=read_json(path/"COMMIT.json");target=result["installation"];read_edition(root,target["source_identity"])
        need(target["directory"]==str(root),"installation_changed","The retained transition identifies another directory.")
        if (root/"installation.json").exists():
            current=installation(root,False);before=read_json(path/"BEFORE.json") if (path/"BEFORE.json").exists() else None
            need(current==target or kind=="adopt_source" and current==before,"installation_changed","Receive the exact retained original source transition.")
        if (path/"TARGET_HANDOVER.json").exists():
            handover=read_json(path/"TARGET_HANDOVER.json",MAX_SOURCE_BYTES)
            # Source adoption is serialized by the operator lease. A completed
            # marker must never overwrite any later browser edition.
            if not (root/"installation.json").exists() or read_json(root/"installation.json")!=target:
                save(root/"workspace"/"CURRENT.json",handover)
        save(root/"installation.json",target);selected_engine(root,target,"inspect")
        finish(path,result)
    if result is None:return None
    if result.get("installation"):
        current=installation(root);need(current["installation_id"]==result["installation"]["installation_id"],"installation_changed","The directory belongs to another installation.")
        selected_engine(root,current,"inspect")
    for key in ("application","handover","archive"):
        original=request.get(key)
        if original and Path(original["path"]).exists():need(input_file(original["path"])==original,"input_changed","A surviving selected original input changed: "+key)
